function evalRPN(tokens) {
  const st = []
  for (const tk of tokens) {
    if (tk === '+' || tk === '-' || tk === '*' || tk === '/') {
      const b = st.pop()
      const a = st.pop()
      if (tk === '+') st.push(a + b)
      else if (tk === '-') st.push(a - b)
      else if (tk === '*') st.push(a * b)
      else st.push(Math.trunc(a / b))
    } else st.push(Number(tk))
  }
  return st.pop()
}

